from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject
from taf.gnb.oam.coam.cu.schemas.internal.asm.cells_summary_v1 import CuCellsSummaryASMV1


class Alarm(SchemaObject):
    uuid = SchemaField(name="uuid")
    severity = SchemaField(name="severity")
    alarm_id = SchemaField(name="alarmId")
    alarm_name = SchemaField(name="alarmName")
    fault_id = SchemaField(name="faultId")
    fault_name = SchemaField(name="faultName")

    def __init__(self, uuid, severity, alarm_id, alarm_name, fault_id, fault_name):
        super(Alarm, self).__init__()
        self.uuid = uuid
        self.severity = severity
        self.alarm_id = alarm_id
        self.alarm_name = alarm_name
        self.fault_id = fault_id
        self.fault_name = fault_name


class DistNames(SchemaObject):
    config = SchemaField(name="config")
    runtime = SchemaField(name="runtime")

    def __init__(self, config, runtime):
        super(DistNames, self).__init__()
        self.config = config
        self.runtime = runtime


class CellGroup(SchemaObject):
    id = SchemaField(name="id")
    cell_ids = SchemaField(name="cellIds")

    def __init__(self, id, cell_ids):
        super(CellGroup, self).__init__()
        self.id = id
        self.cell_ids = cell_ids


class GnbDu(SchemaObject):
    id = SchemaField(name="id", not_null=True)
    name = SchemaField(name="name", not_null=True)
    gnb_du_id = SchemaField(name="gnbDuId", not_null=True)
    gnb_du_name = SchemaField(name="gnbDuName")
    administrative_state = SchemaField(name="administrativeState", not_null=True)
    f1_link_status = SchemaField(name="f1LinkStatus", not_null=True)
    alarms = SchemaField(name="alarms", klass=Alarm, many=True)
    cell_groups = SchemaField(name="cellGroups", klass=CellGroup, many=True)
    cells_summary = SchemaField(name="cellsSummary", klass=CuCellsSummaryASMV1)
    dist_names = SchemaField(name="distNames", klass=DistNames)

    def __init__(self, id, name, gnb_du_id, gnb_du_name, administrative_state, f1_link_status, alarms, cell_groups,
                 cells_summary, dist_names):
        super(GnbDu, self).__init__()
        self.id = id
        self.name = name
        self.gnb_du_id = gnb_du_id
        self.gnb_du_name = gnb_du_name
        self.administrative_state = administrative_state
        self.f1_link_status = f1_link_status
        self.alarms = alarms
        self.cell_groups = cell_groups
        self.cells_summary = cells_summary
        self.dist_names = dist_names


class DusDiffASMV1(SchemaObject):
    revision = SchemaField(name="revision", not_null=True)
    created = SchemaField(name="created", klass=GnbDu, many=True)
    updated = SchemaField(name="updated", klass=GnbDu, many=True)
    removed = SchemaField(name="removed", not_null=True)

    def __init__(self, revision, created, updated, removed):
        super(DusDiffASMV1, self).__init__()
        self.revision = revision
        self.created = created
        self.updated = updated
        self.removed = removed
